 */
namespace AgnesWebSearch {
  export type WebSearchInput = {
    /**
     * Short focused search query. Use site:domain.com in the query for strict source targeting.
     * Optional when `queries` is provided.
     */
    query?: string | undefined;
    /**
     * Multiple independent queries to run in one call (internally parallel). Prefer this over
     * many separate web_search calls when several angles are already known.
     */
    queries?: string[] | undefined;
    /**
     * Optional provider: auto, bff, searchfree, searxng, jina_search, exa_mcp, or duckduckgo.
     */
    provider?: string | null | undefined;
    /**
     * Optional search mode: normal, research, deep_research, or wide_research.
     */
    mode?: string | null | undefined;
    /**
     * Maximum results to return. Defaults to 5, capped at 10.
     */
    max_results?: number | null | undefined;
    /**
     * DuckDuckGo/SearXNG region, for example us-en, wt-wt, uk-en, cn-zh.
     */
    region?: string | null | undefined;
    /**
     * Safe search setting: strict, moderate, or off.
     */
    safe_search?: string | null | undefined;
    /**
     * Optional freshness filter: day, week, month, or year.
     */
    time_range?: string | null | undefined;
    /**
     * Restrict results to these domains.
     */
    include_domains?: string[] | undefined;
    /**
     * Exclude these domains.
     */
    exclude_domains?: string[] | undefined;
  };

  export type WebSearchOutput = {
    kind: string;

    query: string;

    provider: string;

    results: WebSearchOutputWebSearchResult[];

    sources?: WebSearchOutputWebSearchSource[] | undefined;

    errors?: WebSearchOutputSearchSourceError[] | undefined;
  };

  export type WebSearchOutputWebSearchResult = {
    title: string;

    url: string;

    snippet: string;

    rank: number;

    source: string;
  };

  export type WebSearchOutputWebSearchSource = {
    provider: string;

    source_type: string;

    results: WebSearchOutputWebSearchResult[];

    error?: string | null | undefined;

    elapsed_ms: number;
  };

  export type WebSearchOutputSearchSourceError = {
    provider: string;

    message: string;

    elapsed_ms: number;
  };

  /**
   * Search the public web and return titles, URLs, and snippets. Prefer explicitly requested or configured search tools. Batch known query angles; use research modes for broad evidence and read important URLs before relying on precise claims.
   */
  export async function webSearch(input: WebSearchInput = {}): Promise<WebSearchOutput>
}

/**
 *
 */
namespace Developer {
  export type ReadInput = {
    /**
     * Absolute path to the file to read.
     */
    path: string;
    /**
     * Line number to start reading from (1-based).
     */
    line?: number | null | undefined;
    /**
     * Maximum number of lines to read.
     */
    limit?: number | null | undefined;
  };

  /**
   * Fallback UTF-8 text-file reader when shell fails or is unavailable. You MUST try shell first. Do not use it for binary formats such as PDF, DOCX, or XLSX; use a matching extension tool instead. Accepts absolute paths, including files outside the current workspace when the user provides them. Optionally start at a 1-based line and limit how many lines are returned.
   */
  export async function read(input: ReadInput): Promise<any>

  export type WriteInput = {
    path: string;

    content: string;
    /**
     * Set true only when the user explicitly requested this workspace-external destination.
     */
    user_specified_output?: boolean | undefined;
  };

  /**
   * Create or overwrite a UTF-8 text file. Do not use it for binary formats such as PDF, DOCX, XLSX, PPTX, or XMIND; use a matching extension tool instead. Creates parent directories if needed. In Full access (auto) mode, destinations outside the current workspace are denied without a confirmation prompt, regardless of user_specified_output. In approval modes, for an external destination explicitly requested by the user, set user_specified_output=true and wait for this call's confirmation; otherwise the write is denied.
   */
  export async function write(input: WriteInput): Promise<any>

  export type ShellInput = {
    command: string;
    /**
     * Request network access for this invocation; requires tool approval or Full access (Auto) mode.
     */
    network?: boolean | undefined;
    /**
     * Maximum time in seconds to allow the command to run before it is killed.
     * If omitted, defaults to DEFAULT_EXTENSION_TIMEOUT.
     */
    timeout_secs?: number | null | undefined;
  };

  export type ShellOutput = {
    stdout: string;

    stderr: string;
    /**
     * Process exit code. 0 indicates success, non-zero indicates failure.
     * Absent if the process was terminated by a signal.
     */
    exit_code?: number | null | undefined;
    /**
     * Unix signal that terminated the process.
     */
    termination_signal?: number | null | undefined;
    /**
     * True if the command was killed because it exceeded the timeout.
     */
    timed_out?: boolean | undefined;
    /**
     * True if the command was killed because the active turn was cancelled.
     */
    cancelled?: boolean | undefined;
    /**
     * True if output collection was cut short after the shell exited.
     */
    output_truncated?: boolean | undefined;
    /**
     * Error reported by output collection after process exit.
     */
    output_collection_error?: string | null | undefined;
  };

  /**
   * Execute a shell command in the current dir. Commands run under `bash` (set AGNES_SHELL to override) - write command strings in that shell's syntax, which may differ from the user's interactive terminal. This platform does not expose the Windows `shell` selection parameter. Honor any user-requested interpreter/version constraints; report an unavailable or incompatible environment instead of silently switching interpreters. Inspect stderr and verify expected results even when exit_code is zero. Returns stdout and stderr as separate fields. Each stream is limited to 2000 lines; longer outputs are saved to a temporary file. Ordinary shell commands have network access disabled by the OS sandbox by default. Full access (Auto) mode or approval of this shell call enables network access for the invocation and its descendants. In other modes, set network=true to request network access for a call that would otherwise run without approval. Existing file restrictions remain in place. Managed CLI invocations retain their own execution policy. Hidden credential files or environment variables do not prove the host has no credentials.
   */
  export async function shell(input: ShellInput): Promise<ShellOutput>
}

/**
 *
 */
namespace Computercontroller {
  export type DocxToolInput = {
    /**
     * Path to the DOCX file
     */
    path: string;
    /**
     * Operation to perform on the DOCX. Enum for operation parameter in docx_tool. One of: extract_text: Extract all text content and structure from the DOCX; update_doc: Create a new DOCX or update existing one with provided content
     */
    operation: "extract_text" | "update_doc";
    /**
     * Content to write (required for update_doc operation)
     */
    content?: string | null | undefined;
    /**
     * Additional parameters for update_doc operation
     */
    params?: DocxToolInputDocxUpdateParams | null | undefined;
  };

  /**
   * Additional parameters for update_doc operation
   */
  export type DocxToolInputDocxUpdateParams = {
    /**
     * Update mode (default: append). Enum for update mode in docx_tool params. One of: append: Add content to end of document (default); replace: Replace specific text with new content; structured: Add content with specific heading level and styling; add_image: Add an image to the document (with optional caption)
     */
    mode?: "append" | "replace" | "structured" | "add_image" | undefined;
    /**
     * Text to replace (required for replace mode)
     */
    old_text?: string | null | undefined;
    /**
     * Heading level for structured mode (e.g., 'Heading1', 'Heading2')
     */
    level?: string | null | undefined;
    /**
     * Path to the image file (required for add_image mode)
     */
    image_path?: string | null | undefined;
    /**
     * Image width in pixels (optional)
     */
    width?: number | null | undefined;
    /**
     * Image height in pixels (optional)
     */
    height?: number | null | undefined;
    /**
     * Styling options for the text
     */
    style?: DocxToolInputDocxTextStyle | null | undefined;
  };

  /**
   * Styling options for text in docx_tool
   */
  export type DocxToolInputDocxTextStyle = {
    /**
     * Make text bold
     */
    bold?: boolean | null | undefined;
    /**
     * Make text italic
     */
    italic?: boolean | null | undefined;
    /**
     * Make text underlined
     */
    underline?: boolean | null | undefined;
    /**
     * Font size in points
     */
    size?: number | null | undefined;
    /**
     * Text color in hex format (e.g., 'FF0000' for red)
     */
    color?: string | null | undefined;
    /**
     * Text alignment
     */
    alignment?: "left" | "center" | "right" | "justified" | null | undefined;
  };

  /**
   *
   *             Process DOCX files to extract text and create/update documents.
   *             Supports operations:
   *             - extract_text: Extract all text content and structure (headings, TOC) from the DOCX
   *             - update_doc: Create a new DOCX or update existing one with provided content
   *               Modes:
   *               - append: Add content to end of document (default)
   *               - replace: Replace specific text with new content
   *               - structured: Add content with specific heading level and styling
   *               - add_image: Add an image to the document (with optional caption)
   *
   *             Use this when there is a .docx file that needs to be processed or created.
   *
   */
  export async function docxTool(input: DocxToolInput): Promise<any>
}

